17	        long projectsCount = projects.count();
18	        BigDecimal outstandingTotal = invoices.findByStatusOrderByIdAsc("SENT").stream()
19	                .map(Invoice::getAmount)
20	                .reduce(BigDecimal.ZERO, BigDecimal::add);
21	        response.send(new DashboardView(clientsCount, projectsCount, outstandingTotal));
