1	package net.officefloor.hq.app;
2	
3	import java.util.List;
4	import java.util.Map;
5	import org.springframework.context.annotation.Profile;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.web.bind.annotation.PostMapping;
8	import org.springframework.web.bind.annotation.RequestBody;
9	import org.springframework.web.bind.annotation.RequestMapping;
10	import org.springframework.web.bind.annotation.RestController;
11	
12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // project references client via FK; H2 refuses TRUNCATE on a referenced table, so drop
36	        // referential integrity for the duration of the clear, then restore it.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        jdbc.execute("TRUNCATE TABLE note RESTART IDENTITY");
39	        jdbc.execute("TRUNCATE TABLE project_tag RESTART IDENTITY");
40	        jdbc.execute("TRUNCATE TABLE tag RESTART IDENTITY");
41	        jdbc.execute("TRUNCATE TABLE task RESTART IDENTITY");
42	        jdbc.execute("TRUNCATE TABLE payment RESTART IDENTITY");
43	        jdbc.execute("TRUNCATE TABLE line_item RESTART IDENTITY");
44	        jdbc.execute("TRUNCATE TABLE invoice RESTART IDENTITY");
45	        jdbc.execute("TRUNCATE TABLE project RESTART IDENTITY");
46	        jdbc.execute("TRUNCATE TABLE contact RESTART IDENTITY");
47	        jdbc.execute("TRUNCATE TABLE client RESTART IDENTITY");
48	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
49	    }
50	
51	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
52	    @PostMapping("/seed")
53	    @SuppressWarnings("unchecked")
54	    public void seed(@RequestBody Map<String, Object> fixture) {
55	        List<Map<String, Object>> clients =
56	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
57	        for (Map<String, Object> client : clients) {
58	            jdbc.update("INSERT INTO client (id, name, email) VALUES (?, ?, ?)",
59	                    ((Number) client.get("id")).longValue(), client.get("name"), client.get("email"));
60	        }
61	        List<Map<String, Object>> projects =
62	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
63	        for (Map<String, Object> project : projects) {
64	            Object status = project.getOrDefault("status", "ACTIVE");
65	            boolean archived = Boolean.TRUE.equals(project.getOrDefault("archived", Boolean.FALSE));
66	            Object budgetValue = project.get("budget");
67	            java.math.BigDecimal budget = budgetValue == null ? java.math.BigDecimal.ZERO
68	                    : new java.math.BigDecimal(budgetValue.toString());
69	            jdbc.update(
70	                    "INSERT INTO project (id, name, client_id, status, archived, budget) "
71	                            + "VALUES (?, ?, ?, ?, ?, ?)",
72	                    ((Number) project.get("id")).longValue(), project.get("name"),
73	                    ((Number) project.get("clientId")).longValue(), status, archived, budget);
74	        }
75	        List<Map<String, Object>> tasks =
76	                (List<Map<String, Object>>) fixture.getOrDefault("tasks", List.of());
77	        for (Map<String, Object> task : tasks) {
78	            Object done = task.getOrDefault("done", Boolean.FALSE);
79	            jdbc.update("INSERT INTO task (id, project_id, title, done) VALUES (?, ?, ?, ?)",
80	                    ((Number) task.get("id")).longValue(),
81	                    ((Number) task.get("projectId")).longValue(), task.get("title"),
82	                    Boolean.TRUE.equals(done));
83	        }
84	        List<Map<String, Object>> notes =
85	                (List<Map<String, Object>>) fixture.getOrDefault("notes", List.of());
86	        long maxNoteId = 0;
87	        for (Map<String, Object> note : notes) {
88	            long noteId = ((Number) note.get("id")).longValue();
89	            maxNoteId = Math.max(maxNoteId, noteId);
90	            jdbc.update(
91	                    "INSERT INTO note (id, target_type, target_id, body, at) VALUES (?, ?, ?, ?, ?)",
92	                    noteId, note.get("targetType"),
93	                    ((Number) note.get("targetId")).longValue(), note.get("text"),
94	                    java.sql.Timestamp.from(java.time.Instant.parse(note.get("at").toString())));
95	        }
96	        if (maxNoteId > 0) {
97	            // Seeding explicit ids does not advance H2's IDENTITY sequence, so a note created later
98	            // through the API would collide on id=1. Nudge the sequence past the seeded ids.
99	            jdbc.execute("ALTER TABLE note ALTER COLUMN id RESTART WITH " + (maxNoteId + 1));
100	        }
101	        List<Map<String, Object>> tags =
102	                (List<Map<String, Object>>) fixture.getOrDefault("tags", List.of());
103	        for (Map<String, Object> tag : tags) {
104	            jdbc.update("INSERT INTO tag (id, name) VALUES (?, ?)",
105	                    ((Number) tag.get("id")).longValue(), tag.get("name"));
106	        }
107	        List<Map<String, Object>> projectTags =
108	                (List<Map<String, Object>>) fixture.getOrDefault("projectTags", List.of());
109	        for (Map<String, Object> projectTag : projectTags) {
110	            jdbc.update("INSERT INTO project_tag (project_id, tag_id) VALUES (?, ?)",
111	                    ((Number) projectTag.get("projectId")).longValue(),
112	                    ((Number) projectTag.get("tagId")).longValue());
113	        }
114	        List<Map<String, Object>> contacts =
115	                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
116	        for (Map<String, Object> contact : contacts) {
117	            jdbc.update(
118	                    "INSERT INTO contact (id, client_id, name, email, role) VALUES (?, ?, ?, ?, ?)",
119	                    ((Number) contact.get("id")).longValue(),
120	                    ((Number) contact.get("clientId")).longValue(), contact.get("name"),
121	                    contact.get("email"), contact.get("role"));
122	        }
123	        List<Map<String, Object>> invoices =
124	                (List<Map<String, Object>>) fixture.getOrDefault("invoices", List.of());
125	        for (Map<String, Object> invoice : invoices) {
126	            Object status = invoice.getOrDefault("status", "DRAFT");
127	            Object issuedDate = invoice.get("issuedDate");
128	            Object dueDate = invoice.get("dueDate");
129	            long invoiceId = ((Number) invoice.get("id")).longValue();
130	            // An invoice's amount is the sum of its line items (quantity times unit price); work it
131	            // out here so a fixture lists the things being charged for, not a pre-computed figure.
132	            // A fixture may still pass an explicit amount for an invoice with no line items.
133	            List<Map<String, Object>> lineItems =
134	                    (List<Map<String, Object>>) invoice.getOrDefault("lineItems", null);
135	            java.math.BigDecimal amount;
136	            if (lineItems != null) {
137	                amount = java.math.BigDecimal.ZERO;
138	                for (Map<String, Object> lineItem : lineItems) {
139	                    java.math.BigDecimal unitPrice =
140	                            new java.math.BigDecimal(lineItem.get("unitPrice").toString());
141	                    int qty = ((Number) lineItem.get("qty")).intValue();
142	                    amount = amount.add(unitPrice.multiply(java.math.BigDecimal.valueOf(qty)));
143	                }
144	            } else {
145	                lineItems = List.of();
146	                Object explicit = invoice.get("amount");
147	                amount = explicit == null ? java.math.BigDecimal.ZERO
148	                        : new java.math.BigDecimal(explicit.toString());
149	            }
150	            jdbc.update(
151	                    "INSERT INTO invoice (id, project_id, amount, status, issued_date, due_date) "
152	                            + "VALUES (?, ?, ?, ?, ?, ?)",
153	                    invoiceId, ((Number) invoice.get("projectId")).longValue(), amount, status,
154	                    issuedDate == null ? null : java.sql.Date.valueOf(issuedDate.toString()),
155	                    dueDate == null ? null : java.sql.Date.valueOf(dueDate.toString()));
156	            for (Map<String, Object> lineItem : lineItems) {
157	                jdbc.update(
158	                        "INSERT INTO line_item (id, invoice_id, description, quantity, unit_price) "
159	                                + "VALUES (?, ?, ?, ?, ?)",
160	                        ((Number) lineItem.get("id")).longValue(), invoiceId,
161	                        lineItem.get("description"),
162	                        ((Number) lineItem.get("qty")).intValue(),
163	                        new java.math.BigDecimal(lineItem.get("unitPrice").toString()));
164	            }
165	        }
166	        List<Map<String, Object>> payments =
167	                (List<Map<String, Object>>) fixture.getOrDefault("payments", List.of());
